const sales = [
  { item: "sugar", qty: 3, price: 180 },
  { item: "rice",  qty: 2, price: 340 },
  { item: "oil",   qty: 1, price: 560 },
  { item: "tea",   qty: 5, price: 750 },
  { item: "salt",  qty: 4, price: 60 }
];

const lineTotal = s => s.qty * s.price;
const withGst = (amount, rate = 18) => amount + (amount * rate / 100);
const pad = (s, n) => String(s).padEnd(n);
const padL = (s, n) => String(s).padStart(n);

console.log("ITEM        QTY   PRICE    TOTAL");
console.log("-".repeat(36));

const rows = [...sales].sort((a, b) => lineTotal(b) - lineTotal(a));

for (const s of rows) {
  console.log(
    pad(s.item, 11) + padL(s.qty, 3) + padL(s.price, 8) + padL(lineTotal(s), 9)
  );
}

const grand = sales.reduce((sum, s) => sum + lineTotal(s), 0);

console.log("-".repeat(36));
console.log(pad("Subtotal", 22) + padL(grand, 9));
console.log(pad("With GST", 22) + padL(withGst(grand).toFixed(0), 9));

const biggest = rows[0];
console.log(`\nBiggest line: ${biggest.item}`);
